from dataclasses import dataclass
from decimal import Decimal, InvalidOperation
from typing import List, Set, Union

from .aggregate import AggregatedData


@dataclass
class ValidationError:
    reason: str


def validate_output(
    table: str, data: AggregatedData
) -> Union[str, ValidationError]:
    """Validate the formatted table against the aggregated data.

    Checks:
    1. Every period from the input appears as a column header.
    2. The TOTAL column values match the sum of the row's period values.
    3. No column is narrower than its header.

    Returns the table string if valid, or a ValidationError.
    """
    lines = table.splitlines()
    if not lines:
        return ValidationError(reason="table is empty")

    header_line = lines[0]

    # --- Check 1: all periods appear as column headers ---
    for period in data.periods:
        if period not in header_line:
            return ValidationError(
                reason=f"period {period!r} is missing from table header"
            )

    # --- Parse column positions from the header line ---
    # Split on 2+ spaces to find column tokens and their positions.
    col_tokens = _split_with_positions(header_line)

    if not col_tokens:
        return ValidationError(reason="table header has no columns")

    # --- Check 3: no column narrower than its header ---
    # We determine column widths by looking at how wide each column field is
    # across all rows. The column position boundaries come from the header.
    # Simpler: compare header token width vs same column in data rows.
    # We'll parse each row using the same field widths inferred from header.
    col_starts = [pos for _, pos in col_tokens]
    col_names = [tok for tok, _ in col_tokens]

    for row_line in lines[1:]:
        fields = _extract_fields(row_line, col_starts)
        for ci, (col_name, field_val) in enumerate(zip(col_names, fields)):
            # Width of displayed column: from col_start to next col_start - padding
            col_display_width = len(col_name)
            if len(field_val.strip()) > col_display_width:
                # This means content is wider than header
                return ValidationError(
                    reason=f"column {col_name!r} is narrower than its content"
                )

    # --- Check 2: TOTAL column matches sum of period values for each row ---
    # Find index of TOTAL column
    total_col_idx = None
    for ci, (tok, _) in enumerate(col_tokens):
        if tok == "TOTAL":
            total_col_idx = ci
            break

    if total_col_idx is None:
        return ValidationError(reason="TOTAL column not found in header")

    for row_line in lines[1:]:
        fields = _extract_fields(row_line, col_starts)
        if not fields:
            continue

        row_label = fields[0].strip()
        # Get period value fields (columns 1..total_col_idx-1)
        period_fields = fields[1:total_col_idx]
        total_field = fields[total_col_idx] if total_col_idx < len(fields) else ""

        try:
            period_sum = sum(_parse_formatted_value(f) for f in period_fields)
            total_val = _parse_formatted_value(total_field)
        except (ValueError, InvalidOperation):
            # Can't parse; skip check for this row
            continue

        # Allow small floating point tolerance
        if abs(period_sum - total_val) > Decimal("0.005"):
            return ValidationError(
                reason=(
                    f"TOTAL mismatch in row {row_label!r}: "
                    f"sum of periods={period_sum}, TOTAL column={total_val}"
                )
            )

    return table


def _split_with_positions(line: str):
    """Return list of (token, start_position) from a line, splitting on 2+ spaces."""
    tokens = []
    i = 0
    n = len(line)
    while i < n:
        # Skip spaces
        if line[i] == " ":
            i += 1
            continue
        # Read token
        start = i
        while i < n and line[i] != " ":
            i += 1
        token = line[start:i]
        tokens.append((token, start))
    return tokens


def _extract_fields(line: str, col_starts: List[int]) -> List[str]:
    """Extract fields from a data row using column start positions."""
    fields = []
    for i, start in enumerate(col_starts):
        end = col_starts[i + 1] if i + 1 < len(col_starts) else len(line)
        fields.append(line[start:end])
    return fields


def _parse_formatted_value(s: str) -> Decimal:
    """Parse a formatted value string back to Decimal."""
    s = s.strip()
    if not s:
        return Decimal(0)
    negative = s.startswith("-")
    if negative:
        s = s[1:]
    # Remove $ and commas
    s = s.lstrip("$").replace(",", "")
    val = Decimal(s)
    return -val if negative else val

