            return ValidationError(
                reason=f"column {col_name!r} is narrower than its header"
            )

    # Additionally verify data row content fits within allocated widths
    for row_line in lines[1:]:
        for i, (col_start, col_width) in enumerate(zip(col_starts, col_widths)):
