    for ci, name in enumerate(col_names):
        if name == "TOTAL":
            total_col_idx = ci
            break

    if total_col_idx is None:
        return ValidationError(reason="TOTAL column not found in header")

    for row_line in lines[1:]:
        if not row_line.strip():
            continue

        fields = [
            _get_field(row_line, col_starts[i], col_widths[i])
            for i in range(len(col_names))
        ]

        row_label = fields[0].strip()
        period_fields = fields[1:total_col_idx]
        total_field = fields[total_col_idx] if total_col_idx < len(fields) else ""

        try:
            period_sum = sum(_parse_formatted_value(f) for f in period_fields)
            total_val = _parse_formatted_value(total_field)
        except (ValueError, InvalidOperation):
            continue

        if abs(period_sum - total_val) > Decimal("0.005"):
            return ValidationError(
                reason=(
                    f"TOTAL mismatch in row {row_label!r}: "
                    f"sum of periods={period_sum}, TOTAL column={total_val}"
                )
            )

    return table


def _split_with_positions(line: str) -> List[tuple]:
    """Return list of (token, start_position) splitting on whitespace."""
    tokens = []
    i = 0
    n = len(line)
    while i < n:
        if line[i] == " ":
            i += 1
            continue
        start = i
        while i < n and line[i] != " ":
            i += 1
        tokens.append((line[start:i], start))
    return tokens


def _get_field(line: str, col_start: int, col_width: int) -> str:
    """Extract the field at [col_start, col_start + col_width] from a line."""
    end = col_start + col_width
    if col_start >= len(line):
        return ""
    return line[col_start:min(end, len(line))]


